<template>
 <section class="contract-form">
  <header><span>ACUERDO COMERCIAL · SISTEMAS</span><h2>De la propuesta al acuerdo con tu cliente</h2><p>El contrato incorpora los productos, módulos, alcance, implementación, servicios y anualidad de la proforma guardada.</p></header>
  <p v-if="loading" role="status">Cargando los datos de la propuesta…</p>
  <template v-else>
   <div v-if="latest" class="contract-saved"><strong>Contrato guardado · versión {{latest.version}}</strong><p v-if="latest.stale">La proforma cambió después de generar esta versión. Revisa los términos y genera una nueva versión.</p><p v-else>Esta versión conserva los términos e importes con los que fue generada.</p><a :href="latest.url" target="_blank" rel="noopener">Ver / imprimir contrato PDF</a><a :href="latest.url+'&amp;descargar=1'" target="_blank" rel="noopener">Descargar PDF</a></div>
   <form @submit.prevent="generate">
    <h3>1. Identificación del contrato y las partes</h3>
    <div class="contract-grid"><label>Número del contrato (correlativo)<input :value="form.numeroContrato" readonly aria-readonly="true" maxlength="40"></label><label>Lugar de celebración<input v-model.trim="form.ciudad" maxlength="100" :disabled="busy" placeholder="Ciudad acordada"></label></div>
    <p class="contract-hint">El correlativo es independiente de la proforma y se asigna al guardar. Las nuevas versiones conservan el mismo número. Revisa los documentos de los firmantes antes de generar el contrato.</p>
    <div class="contract-grid"><label>Nombre o razón social del cliente *<input v-model.trim="form.cliente" required maxlength="180" :disabled="busy"></label><label>DNI, RUC u otro documento *<input v-model.trim="form.documento" required maxlength="20" :disabled="busy"></label></div>
    <label>Domicilio del cliente *<input v-model.trim="form.direccion" required maxlength="500" :disabled="busy"></label>
    <div class="contract-grid"><label>Consultor de TI *<input v-model.trim="form.consultor" required maxlength="180" :disabled="busy"></label><label>Gerente general *<input v-model.trim="form.representanteProveedor" required maxlength="180" :disabled="busy"></label></div>
    <div class="contract-grid"><label>Documento del consultor<input v-model.trim="form.documentoConsultor" maxlength="20" :disabled="busy" placeholder="DNI u otro documento"></label><label>Documento de la gerente general<input v-model.trim="form.documentoRepresentanteProveedor" maxlength="20" :disabled="busy" placeholder="Verifica el documento vigente"></label></div>
    <div class="contract-grid"><label>Representante legal del cliente<input v-model.trim="form.representanteCliente" maxlength="180" :disabled="busy" placeholder="Cuando corresponda; de lo contrario firma el cliente"></label><label>Documento del representante del cliente<input v-model.trim="form.documentoRepresentanteCliente" maxlength="20" :disabled="busy" placeholder="DNI u otro documento del representante"></label></div>
    <div class="contract-signatories" aria-label="Orden de firmas del contrato"><div><span>IZQUIERDA · CONSULTOR DE TI</span><strong>{{form.consultor}}</strong></div><div><span>CENTRO · CLIENTE / REPRESENTANTE LEGAL</span><strong>{{form.representanteCliente || form.cliente || 'Nombre del cliente'}}</strong></div><div><span>DERECHA · GERENTE GENERAL</span><strong>{{form.representanteProveedor}}</strong></div></div>
    <label class="contract-check"><input type="checkbox" v-model="form.incluirRubricaConsultor" :disabled="busy"><span>Incluir la rúbrica de Ing. Jhon H. Medrano Martinez en este contrato</span></label>
    <div v-if="form.incluirRubricaConsultor &amp;&amp; isJhonConsultant" class="contract-rubric-preview"><img src="/nuevo/static/images/consultor-jhon-rubrica-limpia.png" alt="Rúbrica de Ing. Jhon H. Medrano Martinez"><small>Esta imagen se incorporará al espacio del CONSULTOR DE TI en la nueva versión. El documento conserva su estado de borrador para revisión y firma.</small></div>
    <label>Fecha del contrato *<input type="date" v-model="form.fecha" required :disabled="busy"></label>
    <h3>2. Inversión y acuerdo de pago</h3>
    <div class="contract-payment"><div><span>Total de la propuesta</span><strong>S/ {{money(total)}}</strong></div><div><span>{{form.recibido?'Adelanto declarado recibido':'Adelanto pactado'}}</span><strong>S/ {{money(advance)}}</strong></div><div><span>Saldo después del adelanto</span><strong>S/ {{money(balance)}}</strong></div></div>
    <div class="contract-grid"><label>Definir adelanto por<select v-model="form.modoAdelanto" @change="switchMode" :disabled="busy"><option value="porcentaje">Porcentaje del total</option><option value="monto">Monto en soles</option></select></label><label>{{form.modoAdelanto==='porcentaje'?'Adelanto (%)':'Adelanto (S/)'}} *<input type="number" min="0" :max="form.modoAdelanto==='porcentaje'?100:total" step="0.01" v-model.number="form.adelanto" required :disabled="busy"></label></div>
    <p class="contract-hint">Se propone 50 % de adelanto. Puedes cambiar el porcentaje o indicar el monto acordado.</p>
    <label class="contract-check"><input type="checkbox" v-model="form.recibido" :disabled="busy"><span>Confirmo que el cliente ya dejó este adelanto.</span></label>
    <div v-if="form.recibido" class="contract-receipt"><div class="contract-grid"><label>Fecha del adelanto *<input type="date" v-model="form.fechaAdelanto" required :disabled="busy"></label><label>Medio de pago *<select v-model="form.medioAdelanto" required :disabled="busy"><option value="">Seleccionar</option><option>Efectivo</option><option>Transferencia bancaria</option><option>Yape</option><option>Plin</option><option>Tarjeta</option><option>Otro medio acordado</option></select></label></div><label>Referencia de la operación<input v-model.trim="form.referenciaAdelanto" maxlength="120" :disabled="busy"></label><p>Esta declaración se incluye en el contrato. No registra un movimiento de caja ni reemplaza el comprobante de pago.</p></div>
    <label>Cuándo y cómo se paga el saldo *<textarea v-model.trim="form.pagoSaldo" rows="2" required maxlength="1500" :disabled="busy" placeholder="Indica el momento, plazo y medio acordados con el cliente."/></label>
    <label>Fecha acordada para pagar el saldo<input type="date" v-model="form.fechaSaldo" :disabled="busy"></label>
    <p class="contract-hint">Si la fecha todavía no está definida, el contrato indicará que está pendiente de acuerdo con el cliente.</p>
    <h3>3. Vigencia y compromisos acordados</h3>
    <div class="contract-grid"><label>Vigencia de la licencia *<textarea v-model.trim="form.vigenciaLicencia" rows="3" required maxlength="1000" :disabled="busy" placeholder="Indica la duración y las condiciones de uso acordadas."/></label><label>Plazo de implementación *<textarea v-model.trim="form.plazoImplementacion" rows="3" required maxlength="1000" :disabled="busy" placeholder="Indica el plazo, fecha de inicio y condiciones para la entrega."/></label></div>
    <label>Período de soporte<textarea v-model.trim="form.soporteVigencia" rows="2" maxlength="1000" :disabled="busy" placeholder="Duración, inicio de cobertura y renovación acordados."/></label>
    <button type="button" class="contract-secondary" :disabled="busy" @click="useReferencePeriods">Usar plazos del modelo: soporte 12 meses e implementación 10 días</button>
    <p class="contract-hint">Al seleccionar estos plazos reemplazas los campos de soporte e implementación. Revisa el inicio y la modalidad acordados con el cliente.</p>
    <h3>4. Compromisos de esta contratación</h3>
    <p class="contract-hint">Se incorporarán únicamente los compromisos que selecciones. Los módulos, servicios SUNAT, respaldos y anualidad se toman de la proforma guardada.</p>
    <div class="contract-choice-actions"><button type="button" class="contract-secondary" :disabled="busy" @click="form.compromisos=clauseCatalog.filter(item=>item.recommended).map(item=>item.id)">Seleccionar recomendaciones del modelo</button><button type="button" class="contract-secondary" :disabled="busy" @click="form.compromisos=[]">Limpiar selección</button></div>
    <div class="contract-clause-options"><label v-for="item in clauseCatalog" :key="item.id" class="contract-check"><input type="checkbox" v-model="form.compromisos" :value="item.id" :disabled="busy"><span><b>{{item.name}}</b><small>{{item.text}}</small></span></label></div>
    <h3>5. Condiciones particulares y datos de pago</h3>
    <label>Presentación de las cuentas bancarias<select v-model="form.formatoCuentas" :disabled="busy"><option value="imagen">Imagen de cuentas de la proforma</option><option value="texto">Cuentas escritas</option><option value="ambos">Imagen y cuentas escritas</option></select></label>
    <div v-if="form.formatoCuentas!=='texto'" class="contract-bank-preview"><span>CUENTAS BANCARIAS DE LA EMPRESA</span><img src="/resources/images/cuentas.png" alt="Cuentas bancarias de la empresa, como en la proforma"><small>Se incorporará esta imagen al apartado Información de pago del contrato.</small></div>
    <label v-if="form.formatoCuentas!=='imagen'">Cuentas y datos para el pago *<textarea v-model.trim="form.cuentasPago" rows="4" required maxlength="3000" :disabled="busy" placeholder="Titular: …&#10;Banco: …&#10;Cuenta: …&#10;CCI: …"/></label>
    <label>Acuerdos particulares<textarea v-model.trim="form.condicionesEspeciales" rows="3" maxlength="6000" :disabled="busy" placeholder="Usuarios, locales, recursos del VPS, capacidad de almacenamiento u otras condiciones negociadas."/></label>
    <details class="contract-source"><summary>Revisar el alcance que se incorporará</summary><h4>Alcance y módulos</h4><p>{{quote.AlcanceSistema || 'La propuesta no tiene alcance detallado.'}}</p><h4>Implementación</h4><p>{{quote.EntregablesSistema || 'Sin entregables detallados.'}}</p><h4>Servicios y condiciones</h4><p>{{quote.CondicionesSistema || 'Sin condiciones detalladas.'}}</p></details>
    <label class="contract-check"><input type="checkbox" v-model="reviewed" :disabled="busy"><span>Revisé con el cliente los datos, importes y condiciones que se incluirán en el borrador.</span></label>
    <p v-if="error" class="contract-error" role="alert">{{error}}</p><p v-if="success" class="contract-success" role="status">{{success}}</p>
    <footer><small>Se genera un borrador para revisión y firma de las partes. Los anexos detallan los módulos y servicios acordados. Cada nueva versión conserva su propia copia de los términos.</small><button type="submit" :disabled="busy || !reviewed || !sourceHash">{{busy?'Generando contrato…':latest?'Generar nueva versión del contrato':'Generar contrato para revisión'}}</button></footer>
   </form>
  </template>
 </section>
</template>
<script>
import {DEFAULT_CONSULTANT,DEFAULT_MANAGER} from '@/utils/proformaSignatories';
import clauseCatalog from '../../static/data/proforma-contract-clauses.json';
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
export default {
 props:{quoteId:{type:[String,Number],required:true},quote:{type:Object,default:()=>({})}},
 data(){return {clauseCatalog,numberAssigned:false,numberSequence:0,loading:true,busy:false,error:'',success:'',csrf:'',sourceHash:'',total:0,latest:null,reviewed:false,previousMode:'porcentaje',form:{incluirRubricaConsultor:true,numeroContrato:'',ciudad:'',documentoConsultor:'',documentoRepresentanteProveedor:'22641497',documentoRepresentanteCliente:'',soporteVigencia:'12 meses, contados desde la activación del servicio.',compromisos:[],formatoCuentas:'imagen',cuentasPago:'',cliente:'',documento:'',direccion:'',representanteCliente:'',representanteProveedor:DEFAULT_MANAGER,consultor:DEFAULT_CONSULTANT,fecha:today(),modoAdelanto:'porcentaje',adelanto:50,recibido:false,fechaAdelanto:today(),medioAdelanto:'',referenciaAdelanto:'',pagoSaldo:'En una fecha acordada con el cliente.',fechaSaldo:'',vigenciaLicencia:'',plazoImplementacion:'',condicionesEspeciales:''}};},
 computed:{isJhonConsultant(){return this.form.consultor.trim().replace(/\s+/g,' ').toLocaleLowerCase('es-PE')===DEFAULT_CONSULTANT.toLocaleLowerCase('es-PE');},advance(){const v=Number(this.form.adelanto);if(!Number.isFinite(v))return 0;return this.form.modoAdelanto==='porcentaje'?Math.round(Math.round(this.total*100)*v/100)/100:Math.round(v*100)/100;},balance(){return Math.round((this.total-this.advance)*100)/100;}},
 watch:{form:{deep:true,handler(){this.reviewed=false;}},'form.fecha'(){if(!this.loading&&!this.numberAssigned)this.refreshNumber();}},
 mounted(){this.load();},
 methods:{async refreshNumber(){const year=String(this.form.fecha).slice(0,4);if(!/^\d{4}$/.test(year))return;const sequence=++this.numberSequence;try{const r=await fetch('/api/proforma-contract.php?id='+encodeURIComponent(this.quoteId)+'&anio='+year,{credentials:'same-origin'});const data=await r.json();if(sequence!==this.numberSequence)return;if(!r.ok)throw Error(data.error||'No se pudo consultar el correlativo.');this.form.numeroContrato=data.numeroContrato;this.numberAssigned=!!data.numeroAsignado;}catch(e){if(sequence===this.numberSequence)this.error=e.message;}},useReferencePeriods(){this.form.soporteVigencia='12 meses, contados desde la activación del servicio.';this.form.plazoImplementacion='10 días calendario, contados desde la entrega de la información y los accesos acordados con el cliente.';},money(value){return Number(value).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2});},switchMode(){const v=Number(this.form.adelanto)||0;this.form.adelanto=this.form.modoAdelanto==='monto'?Math.round(this.total*v)/100:(this.total?Math.round(v/this.total*10000)/100:50);this.previousMode=this.form.modoAdelanto;},
 async load(){this.loading=true;this.error='';try{const r=await fetch('/api/proforma-contract.php?id='+encodeURIComponent(this.quoteId),{credentials:'same-origin'});const data=await r.json();if(!r.ok)throw Error(data.error||'No se pudo cargar la propuesta.');this.csrf=data.csrf;this.sourceHash=data.sourceHash;this.total=Number(data.total);this.latest=data.contract;this.numberAssigned=!!data.numeroAsignado;const client=data.cliente||{};this.form.cliente=/^clientes? varios?$/i.test(client.nombre||'')?'':client.nombre||'';this.form.documento=/^0+$/.test(client.documento||'')?'':client.documento||'';this.form.direccion=client.direccion||'';this.form.numeroContrato=data.numeroContrato||String(this.quote.Numero||this.quoteId).padStart(3,'0')+'-'+(this.quote.Anio||new Date().getFullYear());if(data.contract && data.contract.form){this.form=Object.assign({},this.form,data.contract.form);this.form.formatoCuentas=data.contract.form.formatoCuentas||(this.form.cuentasPago.trim()?'texto':'imagen');this.form.consultor=this.form.consultor||DEFAULT_CONSULTANT;this.form.representanteProveedor=this.form.representanteProveedor||DEFAULT_MANAGER;if(data.contract.stale&&this.form.recibido){this.form.modoAdelanto='monto';this.form.adelanto=data.contract.form.adelantoCentimos/100;}this.reviewed=false;this.previousMode=this.form.modoAdelanto;}if(data.numeroContrato)this.form.numeroContrato=data.numeroContrato;}catch(e){this.error=e.message;}finally{this.loading=false;}},
 async generate(){if(this.busy||!this.reviewed||!this.sourceHash)return;this.error='';this.success='';if(this.advance<0||this.balance<0){this.error='El adelanto debe estar entre cero y el total de la propuesta.';return;}this.busy=true;try{const r=await fetch('/api/proforma-contract.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Contract-CSRF':this.csrf},body:JSON.stringify(Object.assign({},this.form,{IdProforma:Number(this.quoteId),sourceHash:this.sourceHash,revisado:true}))});const data=await r.json();if(!r.ok)throw Error(data.error||'No se pudo generar el contrato.');this.latest={id:data.id,version:data.version,url:data.url,stale:false};if(data.numeroContrato){this.form.numeroContrato=data.numeroContrato;this.numberAssigned=true;}this.success='Contrato generado. Abre el PDF para revisarlo e imprimirlo; el documento está pendiente de las firmas.';this.$emit('generated',this.latest);}catch(e){this.error=e.message;}finally{this.busy=false;}}
 }
};
</script>
<style scoped>
