11px;line-height:1.6;color:#816370;overflow-wrap:anywhere}.contract-error{background:#fff0f1;padding:10px;color:#ae253b;font-size:12px}.contract-success,.contract-saved{background:#faf2f6;padding:12px;border-radius:6px;font-size:12px;margin-bottom:12px}.contract-saved p{font-size:11px;line-height:1.5;color:#8b6878}.contract-saved a{display:inline-block;margin:4px 14px 0 0;color:#a5223b;text-decoration:underline}.contract-form footer{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-top:16px;padding-top:12px;border-top:1px solid #ecdee4}.contract-form footer small{font-size:10px;line-height:1.5;color:#8d6e7a;max-width:60%}.contract-form button{border:0;padding:11px 15px;border-radius:6px;color:white;background:#b21f3c;font-size:12px;cursor:pointer}.contract-form button:disabled{opacity:.5;cursor:default}@media(max-width:650px){.contract-grid{grid-template-columns:1fr;gap:0}.contract-payment{grid-template-columns:1fr}.contract-payment>div{border-right:0;border-bottom:1px solid #efdee4}.contract-form footer{flex-direction:column;align-items:stretch}.contract-form footer small{max-width:100%}}
.contract-signatories{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;padding:13px 0;margin-bottom:12px;border-top:1px solid #efdee4;border-bottom:1px solid #efdee4}.contract-signatories div{min-width:0;text-align:center}.contract-signatories span{display:block;font-size:8px;letter-spacing:.5px;line-height:1.5;color:#a12942;margin-bottom:5px}.contract-signatories strong{font-size:11px;line-height:1.5;overflow-wrap:anywhere}@media(max-width:650px){.contract-signatories{grid-template-columns:1fr;gap:14px}}
.contract-form .contract-secondary{background:#fff;color:#a5233c;border:1px solid #dfc8d0;padding:8px 11px;font-size:11px;text-align:left}.contract-choice-actions{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.contract-clause-options{padding:13px;border:1px solid #ead9e0;border-radius:7px;background:#fffbfc;margin-bottom:14px}.contract-clause-options .contract-check{margin-bottom:14px}.contract-clause-options .contract-check:last-child{margin-bottom:0}.contract-clause-options b{display:block;font-size:12px;color:#733d4e}.contract-clause-options small{display:block;font-size:11px;font-weight:400;color:#8b6d78;line-height:1.5;margin-top:4px}
.contract-rubric-preview{display:flex;align-items:center;gap:15px;margin:10px 0 18px;padding:12px;border:1px solid #ead9e1;border-radius:6px;background:#fff}.contract-rubric-preview img{width:140px;height:auto;flex-shrink:0}.contract-rubric-preview small{font-size:10px;line-height:1.5;color:#896675}@media(max-width:650px){.contract-rubric-preview{flex-direction:column;align-items:flex-start}}
.contract-bank-preview{padding:12px;border:1px solid #ead9e1;border-radius:6px;margin:0 0 14px;background:#fff}.contract-bank-preview span{display:block;font-size:9px;letter-spacing:.7px;color:#a5233c;font-weight:700}.contract-bank-preview img{display:block;width:100%;height:auto;margin:12px auto;max-width:760px}.contract-bank-preview small{font-size:11px;line-height:1.5;color:#8d6e7a}
</style>
